#include<bits/stdc++.h>

using namespace std;

int main(){
  string s;
  cin >> s;

  map<string,int> mp;
  queue<string> q;

  mp[s]=0;
  q.push(s);

  while(!q.empty()){
    string current=q.front();q.pop();
    if(current=="atcoder"){
      cout << mp[current] << "\n";
      return 0;
    }

    for(int i=1;i<7;i++){
      string next=current;
      swap(next[i-1],next[i]);
      if(mp.find(next)==mp.end()){
        q.push(next);
        mp[next]=mp[current]+1;
      }
    }
  }
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

vector<int> bit;
int sum(int i){
    int s=0;
    while(i>0){
        s+=bit[i];
        i-=i&(-i);
    }
    return s;
}

void add(int i,int x){
    while(i<bit.size()){
        bit[i]+=x;
        i+=i&(-i);
    }
}

int main(){
  bit.resize(10);
  for(int i=0;i<10;i++){bit[i]=0;}

  string s;
  cin >> s;
  map<char,int> mp;
  string atc="*atcoder";
  for(int i=1;i<=7;i++){
    mp[atc[i]]=i;
  }
  vector<int> a={-1};
  for(int i=0;i<7;i++){
    a.push_back(mp[s[i]]);
  }

  int res=0;
  for(int i=1;i<=7;i++){
    res+=(i-1-sum(a[i]));
    add(a[i],1);
  }
  cout << res << "\n";
  return 0;
}
